package run.halo.starter;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import reactor.core.publisher.*;
import run.halo.app.extension.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
class McpMomentServiceTest {
 private static class Harness {
  final ReactiveExtensionClient client=mock(ReactiveExtensionClient.class);final McpConfigService config=mock(McpConfigService.class);final McpImageService images=mock(McpImageService.class);final Map<String,McpMomentDraft> drafts=new HashMap<>();final Map<String,Unstructured> moments=new HashMap<>();final AtomicInteger publicCreates=new AtomicInteger();final AtomicBoolean failAfterPublish=new AtomicBoolean();final McpMomentService service;
  Harness(){var settings=new McpSettings();settings.setEnabled(true);when(config.settings()).thenReturn(Mono.just(settings));when(config.requireWriter(anyString())).thenReturn(Mono.empty());var write=mock(McpWriteConfig.class);var ws=new McpWriteSettings();ws.setAuthorName("blog-owner");ws.setPolicyName("own-policy");when(write.ready()).thenReturn(Mono.just(ws));when(images.images(anyString(),anyList())).thenReturn(Mono.just(List.of()));when(client.fetch(eq(McpMomentDraft.class),anyString())).thenAnswer(i->Mono.justOrEmpty(copy(drafts.get(i.getArgument(1)))));when(client.listAll(eq(McpMomentDraft.class),any(),any())).thenAnswer(i->Flux.fromIterable(new ArrayList<>(drafts.values())));when(client.create(any(McpMomentDraft.class))).thenAnswer(i->{var d=copy(i.getArgument(0));if(drafts.containsKey(d.getMetadata().getName()))return Mono.error(new ResponseStatusException(HttpStatus.CONFLICT));d.getMetadata().setVersion(0L);drafts.put(d.getMetadata().getName(),copy(d));return Mono.just(copy(d));});when(client.update(any(McpMomentDraft.class))).thenAnswer(i->{var d=copy(i.getArgument(0));if(d.getState().equals("PUBLISHED")&&failAfterPublish.compareAndSet(true,false))return Mono.error(new ResponseStatusException(HttpStatus.CONFLICT,"模拟确认状态写入失败"));d.getMetadata().setVersion(Objects.requireNonNullElse(d.getMetadata().getVersion(),0L)+1);drafts.put(d.getMetadata().getName(),copy(d));return Mono.just(copy(d));});when(client.fetch(any(GroupVersionKind.class),anyString())).thenAnswer(i->Mono.justOrEmpty(moments.get(i.getArgument(1))));when(client.create(any(Unstructured.class))).thenAnswer(i->{Unstructured m=i.getArgument(0);moments.put(m.getMetadata().getName(),m);publicCreates.incrementAndGet();return Mono.just(m);});service=new McpMomentService(client,config,write,images,new SubmissionGuard());}
  static McpMomentDraft copy(McpMomentDraft d){if(d==null)return null;var c=new McpMomentDraft();var m=new Metadata();m.setName(d.getMetadata().getName());m.setVersion(d.getMetadata().getVersion());c.setMetadata(m);c.setAgentId(d.getAgentId());c.setAuthorName(d.getAuthorName());c.setContent(d.getContent());c.setImages(d.getImages());c.setFingerprint(d.getFingerprint());c.setState(d.getState());c.setMomentId(d.getMomentId());return c;}
  String create(){return (String)service.create("agent-a","<b>图文瞬间</b>",List.of(),"request-id-1234567890").block().get("id");}
 }
 @Test void agentCreatesPendingOnlyAndRetriesDoNotDuplicate(){var h=new Harness();String id=h.create();var same=h.service.create("agent-a","<b>图文瞬间</b>",List.of(),"request-id-1234567890").block();assertEquals(id,same.get("id"));assertEquals("PENDING",same.get("state"));assertEquals(false,same.get("requiresApproval"));assertEquals(0,h.publicCreates.get());assertThrows(Exception.class,()->h.service.create("agent-a","不同内容",List.of(),"request-id-1234567890").block());assertThrows(Exception.class,()->h.service.status("agent-b",id).block());}
 @Test void humanConfirmationPublishesOnceWithCorrectAuthorAndEscapedHtml(){var h=new Harness();String id=h.create();var result=h.service.review(id,"publish").block();assertEquals("PUBLISHED",result.get("state"));assertEquals(false,result.get("requiresApproval"));h.service.review(id,"publish").block();assertEquals(1,h.publicCreates.get());var moment=h.moments.values().iterator().next();assertEquals("blog-owner",Unstructured.getNestedValue(moment.getData(),"spec","owner").orElseThrow());assertEquals("<p>&lt;b&gt;图文瞬间&lt;/b&gt;</p>",Unstructured.getNestedValue(moment.getData(),"spec","content","html").orElseThrow());assertEquals(id,moment.getMetadata().getAnnotations().get(McpMomentService.DRAFT_ANNOTATION));}
 @Test void publicationStateFailureRetryFindsExistingMomentInsteadOfPublishingTwice(){var h=new Harness();String id=h.create();h.failAfterPublish.set(true);assertThrows(Exception.class,()->h.service.review(id,"publish").block());assertEquals("PUBLISHING",h.drafts.get(id).getState());assertEquals(1,h.publicCreates.get());assertEquals("PUBLISHED",h.service.review(id,"publish").block().get("state"));assertEquals(1,h.publicCreates.get());}
 @Test void rejectedOrRevokedDraftCannotBePublished(){var h=new Harness();String id=h.create();assertEquals("REJECTED",h.service.review(id,"reject").block().get("state"));assertThrows(Exception.class,()->h.service.review(id,"publish").block());assertEquals(0,h.publicCreates.get());var other=new Harness();String pending=other.create();when(other.config.requireWriter("agent-a")).thenReturn(Mono.error(new ResponseStatusException(HttpStatus.FORBIDDEN)));assertThrows(Exception.class,()->other.service.review(pending,"publish").block());assertEquals("PENDING",other.drafts.get(pending).getState());assertEquals(0,other.publicCreates.get());}
 @Test void disappearedImagesBlockPublishingButCanStillBeRejected(){var h=new Harness();String id=h.create();when(h.images.images(eq("agent-a"),anyList())).thenReturn(Mono.error(new IllegalArgumentException("图片已删除")));assertThrows(Exception.class,()->h.service.review(id,"publish").block());assertEquals("PENDING",h.drafts.get(id).getState());assertEquals(0,h.publicCreates.get());var result=h.service.review(id,"reject").block();assertEquals("REJECTED",result.get("state"));assertEquals(false,result.get("requiresApproval"));assertTrue(result.containsKey("imageError"));}
 @Test void invalidImagesAndMissingPermissionNeverCreateDrafts(){var h=new Harness();when(h.images.images(eq("agent-a"),anyList())).thenReturn(Mono.error(new IllegalArgumentException("图片不属于当前Agent")));assertThrows(Exception.class,h::create);assertEquals(0,h.drafts.size());var other=new Harness();when(other.config.requireWriter("agent-a")).thenReturn(Mono.error(new ResponseStatusException(HttpStatus.FORBIDDEN)));assertThrows(Exception.class,other::create);assertEquals(0,other.drafts.size());}
 @Test void confirmationInAgentPublishesDirectlyAndRetriesAreIdempotent(){var h=new Harness();assertThrows(Exception.class,()->h.service.publishConfirmed("agent-a","直接发布",List.of(),"request-direct-123456789",false).block());assertTrue(h.drafts.isEmpty());assertEquals(0,h.publicCreates.get());var result=h.service.publishConfirmed("agent-a","直接发布",List.of(),"request-direct-123456789",true).block();assertEquals("PUBLISHED",result.get("state"));h.service.publishConfirmed("agent-a","直接发布",List.of(),"request-direct-123456789",true).block();assertEquals(1,h.publicCreates.get());}
}
